@script
<script>
window.geofenceEditor = (points, latitude, longitude, radius) => {
    // Keep Leaflet instances outside Alpine's reactive proxies.
    let map=null, polygon=null, officeMarker=null, radiusCircle=null, markers=[], resizeObserver=null;
    return ({
    points:Array.isArray(points)?points.map(point=>({...point})):[], latitude, longitude, radius, copyLabel:'Salin Koordinat',polygonMode:false,
    get map(){return map},
    set map(value){map=value},
    destroy(){resizeObserver?.disconnect();map?.remove();map=null},
    hasOfficeCoordinates(){return this.latitude!==null&&this.latitude!==''&&this.longitude!==null&&this.longitude!==''&&Number.isFinite(Number(this.latitude))&&Number.isFinite(Number(this.longitude))},
    init(){this.$nextTick(()=>this.initializeMap())},
    initializeMap(){
        if(map || !window.L || !this.$refs.map) return;
        this.$refs.map.replaceChildren();
        if(this.$refs.map._leaflet_id) this.$refs.map._leaflet_id=null;
        const hasOffice=this.hasOfficeCoordinates();
        const start=hasOffice?[Number(this.latitude),Number(this.longitude)]:[-7.9778,110.6169];
        map=L.map(this.$refs.map,{
            dragging:true,
            scrollWheelZoom:true,
            doubleClickZoom:false,
            boxZoom:true,
            keyboard:true,
            touchZoom:true,
            inertia:true,
            worldCopyJump:true,
            zoomSnap:1,
            zoomDelta:1,
            wheelDebounceTime:100,
            wheelPxPerZoomLevel:120,
            zoomControl:true,
            zoomAnimation:false,
            fadeAnimation:false,
            markerZoomAnimation:false,
            minZoom:3,
            maxZoom:19
        }).setView(start,hasOffice?18:12);
        map.scrollWheelZoom.enable();
        map.dragging.enable();
        this.addPanControl();
        const roadLayer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{
            minZoom:3,
            maxZoom:19,
            maxNativeZoom:19,
            tileSize:256,
            detectRetina:false,
            updateWhenZooming:false,
            updateWhenIdle:true,
            keepBuffer:2,
            crossOrigin:true,
            attribution:'&copy; OpenStreetMap contributors'
        });
        roadLayer.addTo(map);
        map.on('click',event=>{
            if(!this.polygonMode){this.setOfficePoint(event.latlng.lat,event.latlng.lng);return;}
            if(!this.hasOfficeCoordinates())this.setOfficePoint(event.latlng.lat,event.latlng.lng);
            this.points=[...this.points,{latitude:event.latlng.lat,longitude:event.latlng.lng}];this.syncPoints();
            this.$nextTick(()=>this.draw());
        });
        this.$watch('$wire.maximumAccuracyMeters',value=>{this.radius=Number(value)||100;this.drawOffice()});this.$watch('latitude',()=>this.drawOffice());this.$watch('longitude',()=>this.drawOffice());this.$watch('radius',()=>this.drawOffice());
        if(window.ResizeObserver){
            resizeObserver=new ResizeObserver(()=>map?.invalidateSize({pan:false}));
            resizeObserver.observe(this.$refs.map);
        }
        this.draw();setTimeout(()=>map?.invalidateSize({pan:false}),250);
    },
    addPanControl(){
        const home=map.getCenter();const PanControl=L.Control.extend({options:{position:'topleft'},onAdd(){const box=L.DomUtil.create('div','leaflet-control-pan');L.DomEvent.disableClickPropagation(box);L.DomEvent.disableScrollPropagation(box);const buttons=[['↑','pan-up',()=>map.panBy([0,-180])],['←','pan-left',()=>map.panBy([-180,0])],['⌂','pan-home',()=>map.panTo(home)],['→','pan-right',()=>map.panBy([180,0])],['↓','pan-down',()=>map.panBy([0,180])]];buttons.forEach(([label,className,action])=>{const button=L.DomUtil.create('button',className,box);button.type='button';button.textContent=label;button.setAttribute('aria-label','Geser peta');L.DomEvent.on(button,'click',action)});return box}});new PanControl().addTo(map);
    },
    drawOffice(){
        if(!map)return;officeMarker?.remove();radiusCircle?.remove();officeMarker=radiusCircle=null;
        if(!this.hasOfficeCoordinates())return;const lat=Number(this.latitude),lng=Number(this.longitude);
        const icon=L.divIcon({className:'',html:'<span style="display:block;width:22px;height:22px;border:4px solid white;border-radius:50%;background:#079455;box-shadow:0 2px 8px #0006"></span>',iconSize:[22,22],iconAnchor:[11,11]});
        officeMarker=L.marker([lat,lng],{icon,draggable:true,autoPan:true}).addTo(map).bindTooltip('Titik presensi — geser untuk menyesuaikan',{permanent:true,direction:'top',offset:[0,-12]});
        officeMarker.on('dragend',event=>{const point=event.target.getLatLng();this.setOfficePoint(point.lat,point.lng)});
        radiusCircle=L.circle([lat,lng],{radius:Number(this.radius)||100,color:'#079455',fillColor:'#6ce9a6',fillOpacity:.12,interactive:false}).addTo(map);
    },
    draw(){
        if(!map)return;markers.forEach(marker=>marker.remove());markers=[];polygon?.remove();polygon=null;
        this.drawOffice();
        const snapshot=this.points.map(point=>({latitude:Number(point.latitude),longitude:Number(point.longitude)}));
        if(snapshot.length>=3)polygon=L.polygon(snapshot.map(p=>[p.latitude,p.longitude]),{color:'#1757bb',fillColor:'#4e82ce',fillOpacity:.22,smoothFactor:0,interactive:false}).addTo(map);
        snapshot.forEach((point,index)=>{const marker=L.circleMarker([point.latitude,point.longitude],{radius:15,color:'#fff',weight:3,fillColor:'#175cd3',fillOpacity:1,bubblingMouseEvents:false}).addTo(map).bindTooltip(String(index+1),{permanent:true,direction:'center',className:'geofence-point-label',interactive:false});markers.push(marker)});
    },
    refreshPolygon(){if(polygon)polygon.remove();polygon=null;const snapshot=this.points.map(point=>[Number(point.latitude),Number(point.longitude)]);if(snapshot.length>=3)polygon=L.polygon(snapshot,{color:'#1757bb',fillColor:'#4e82ce',fillOpacity:.22,interactive:false}).addTo(map)},
    setOfficePoint(latitude,longitude){this.latitude=Number(latitude).toFixed(7);this.longitude=Number(longitude).toFixed(7);this.$wire.$set('officeLatitude',this.latitude,false);this.$wire.$set('officeLongitude',this.longitude,false);this.$nextTick(()=>this.drawOffice())},
    remove(index){this.points=this.points.filter((point,itemIndex)=>itemIndex!==index);this.syncPoints();this.$nextTick(()=>this.draw())},removeLast(){this.points=this.points.slice(0,-1);this.syncPoints();this.$nextTick(()=>this.draw())},reset(){this.points=[];this.syncPoints();this.$nextTick(()=>this.draw())},
    syncPoints(){this.$wire.$set('polygonPoints',this.points.map(point=>({latitude:Number(point.latitude),longitude:Number(point.longitude)})),false)},
    focusPolygon(){if(this.points.length)map.fitBounds(this.points.map(p=>[p.latitude,p.longitude]),{padding:[30,30]})},
    focusPoint(){if(this.hasOfficeCoordinates())map.flyTo([Number(this.latitude),Number(this.longitude)],18)},
    async copyCoordinates(){if(!this.hasOfficeCoordinates())return;try{await navigator.clipboard.writeText(Number(this.latitude).toFixed(7)+', '+Number(this.longitude).toFixed(7));this.copyLabel='Tersalin';setTimeout(()=>this.copyLabel='Salin Koordinat',1600)}catch(error){this.copyLabel='Gagal menyalin'}},
    myLocation(){if(!navigator.geolocation){alert('Perangkat ini tidak mendukung GPS.');return}navigator.geolocation.getCurrentPosition(position=>{this.setOfficePoint(position.coords.latitude,position.coords.longitude);map.flyTo([position.coords.latitude,position.coords.longitude],19)},error=>alert(error.code===1?'Izin lokasi ditolak. Aktifkan izin lokasi browser lalu coba lagi.':'Lokasi perangkat tidak dapat ditemukan. Silakan pilih titik pada peta.'),{enableHighAccuracy:true,maximumAge:0,timeout:15000})}
});
};

const initializeGeofenceEditor = () => {
const editorElement = $wire.$el.querySelector('[data-geofence-editor][x-ignore]');
if (editorElement) {
    if (!window.L) {
        const mapElement = editorElement.querySelector('[x-ref="map"]');
        if (mapElement) mapElement.innerHTML = '<div class="as-map-loading as-map-error">Leaflet lokal gagal dimuat. Muat ulang halaman atau periksa folder public/vendor/leaflet.</div>';
    } else {
        Alpine.mutateDom(() => {
            editorElement.removeAttribute('x-ignore');
            delete editorElement._x_ignore;
            delete editorElement._x_ignoreSelf;
            delete editorElement._x_marker;
            const state = JSON.parse(editorElement.dataset.geofenceState);
            editorElement.setAttribute('x-data', 'geofenceEditor('+[state.points,state.latitude,state.longitude,state.radius].map(value=>JSON.stringify(value)).join(',')+')');

            Alpine.initTree(editorElement);
            Alpine.nextTick(() => Alpine.$data(editorElement).initializeMap());
        });
    }
}
};
initializeGeofenceEditor();
Livewire.hook('morph.updated', () => queueMicrotask(initializeGeofenceEditor));
</script>
@endscript
